    """``<provider>:<pipeline_or_dag_id>:<provider_run_id>`` → its parts, or ``None``."""
    if not marker:
        return None
    provider, sep, rest = marker.partition(":")
    if not sep or provider not in ("adf", "airflow", "dbt"):
